import cpmpy as cp
import json
from itertools import product

# We need to find three positive integers A1, A2, A3 (A1 >= A2 >= A3) such that:
# 1. A1 * A2 * A3 = 36
# 2. The sum A1 + A2 + A3 must correspond to a sum that's not unique among possible factor triplets of 36
# 3. There is a unique oldest son (A1 > A2)

# First, find all possible factor triplets of 36 where A1 >= A2 >= A3
factor_triplets = []
for a1 in range(1, 37):
    for a2 in range(1, a1 + 1):
        for a3 in range(1, a2 + 1):
            if a1 * a2 * a3 == 36:
                factor_triplets.append((a1, a2, a3))

# Now find sums that appear more than once (since mathematician needed more info)
sum_counts = {}
for triplet in factor_triplets:
    s = sum(triplet)
    sum_counts[s] = sum_counts.get(s, 0) + 1

# The ambiguous sums are those with count > 1
ambiguous_sums = [s for s, cnt in sum_counts.items() if cnt > 1]

# Now find triplets with these sums and where A1 > A2 (oldest son is unique)
solution = None
for s in ambiguous_sums:
    candidates = [t for t in factor_triplets if sum(t) == s and t[0] > t[1]]
    if len(candidates) == 1:
        solution = candidates[0]
        break

if solution:
    A1, A2, A3 = solution
    solution = {'A1': int(A1), 'A2': int(A2), 'A3': int(A3)}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
